from pathlib import Path
import json,html
out=Path(__file__).resolve().parent
sequences=[]
for label,path in [('Desktop dark','after/dark/timeline.json'),('Desktop light','after/light/timeline.json'),('Mobile','after/mobile/timeline.json'),('Dive Again complete replay','measurements/lifecycle.json')]:
 data=json.loads((out/path).read_text());sequences.append(dict(label=label,frames=data.get('motion',[])))
cards=[]
for p in [out/'baseline/initial.png',out/'baseline/walk.png',out/'baseline/run.png']+sorted((out/'after/dark').glob('*.png'))+sorted((out/'after/light').glob('*.png'))+sorted((out/'after/mobile').glob('*.png'))+sorted((out/'after/responsive').glob('*.png')):
 rel=p.relative_to(out).as_posix();cards.append(f'<a href="{rel}"><img loading="lazy" src="{rel}"><span>{html.escape(rel)}</span></a>')
content='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Phase 05O character evidence</title><style>
body{margin:0;background:#07121c;color:#eaf1f6;font:16px system-ui}main{max-width:1440px;margin:auto;padding:24px}h1{font-size:28px}p{max-width:900px;color:#b9cbd8}a{color:#afd5f7}button,select{padding:10px;background:#17344b;color:white;border:1px solid #476478;border-radius:6px}#player{width:100%;max-height:80vh;object-fit:contain;background:#03080b;margin-top:16px}input{width:70%}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(310px,1fr));gap:16px}.grid a{background:#102331;padding:8px;text-decoration:none}.grid img{width:100%;aspect-ratio:1.6;object-fit:contain}.grid span{font-size:12px;display:block;overflow-wrap:anywhere}#time{margin:10px}
</style><main><h1>Phase 05O — character cinematic evidence</h1><p><a href="report.md">17-part report</a> · <a href="production-diff.patch">Production diff</a> · <a href="measurements/validation.json">Actual validation exits</a></p><p>These are full-scene Chrome production screenshots and screencast frames. Playback retains captured wall-clock spacing. Readbacks and screenshot capture can stall the diagnostic run; use the separate performance traces for frame pacing. Portrait encounters begin at the elevated view.</p><select id="sequence"></select> <button id="play">Play</button> <select id="speed"><option value="1">1×</option><option value="2">2×</option><option value="4">4×</option></select> <span id="time"></span><br><input id="seek" type="range" min="0" value="0"><img id="player"><h2>Before and final full-scene captures</h2><div class="grid">'''+''.join(cards)+'''</div></main><script>
const sequences=DATA,select=document.querySelector('#sequence'),player=document.querySelector('#player'),seek=document.querySelector('#seek'),time=document.querySelector('#time'),play=document.querySelector('#play');let index=0,timer,playing=false;for(const [i,s]of sequences.entries())select.add(new Option(s.label,i));function frames(){return sequences[select.value||0].frames}function show(){const f=frames()[index];if(!f)return;player.src=f.name;seek.value=index;time.textContent=`${index+1}/${frames().length} · ${((f.timestamp-frames()[0].timestamp)||0).toFixed(1)} s`}function pause(){clearTimeout(timer);playing=false;play.textContent='Play'}function tick(){if(!playing)return;const f=frames();show();if(index===f.length-1){pause();return}const wait=Math.max(10,(f[index+1].timestamp-f[index].timestamp)*1000)/Number(document.querySelector('#speed').value);timer=setTimeout(()=>{index++;tick()},wait)}function reset(){pause();index=0;seek.max=frames().length-1;show()}select.onchange=reset;seek.oninput=()=>{pause();index=Number(seek.value);show()};play.onclick=()=>{if(playing){pause();return}if(index===frames().length-1)index=0;playing=true;play.textContent='Pause';tick()};reset();</script></html>'''
(out/'index.html').write_text(content.replace('DATA',json.dumps(sequences)),encoding='utf-8')
print('Created gallery:',len(cards),'screenshots,',sum(len(s['frames'])for s in sequences),'motion frames')
